function StoreItemCard:GetMonthCardRewards(vo)
    local data = {}
    for i, v in pairs(vo.firstRewards) do
        data[v.goodsId] = v.goodsNum
    end

    for i, v in pairs(vo.rewards) do
        if not isNull(data[v.goodsId]) then
            data[v.goodsId] = data[v.goodsId] + v.goodsNum * 30
        else
            data[v.goodsId] = v.goodsNum * 30
        end
    end

    local rewards = {}
    for i, v in pairs(data) do
        table.insert(rewards,{goodsId = i,goodsNum = v})
    end

    return rewards
end

function StoreItemCard:RequestBuyUseCurrency(isSuccess)
    if not isSuccess then
        return
    end
    local monthCard = StoreUtils.GetStoreComp():GetMonthCardInfo(self.monthCardId)
     ---@type MonthCardVo
     local vo =  CfUtils.GetCfVo(AutoIds.IdSetting602, "MonthCardVo" , self.monthCardId)
     if vo.type == MONTH_CARD_TYPE.COMMON then 
        xRecord.af_internal('pay_monthly_card')
     else 
        xRecord.af_internal('pay_forever_card')
     end 
    local goodsId = checkNumber(table.takeFirst(table.keys(monthCard.prices)))
    local dojo = monthCard.prices[tostring(goodsId)]
    local price = checkNumber(dojo.current)
    GameUtils.Request(Interfaces.StoreMonthCardBuy, {productId = monthCard.productId,num = 1, currency = goodsId}, function(request, response)
        GoodsUtils.ConsumeGoods({{goodsId = goodsId,num = price}})
        if response.data.rewards then
            GoodsUtils.DrawRewards(response.data.rewards,true)
            CfUtils.DialogOpen(Constants.UITypeIds.UICommonRewardPop, { rewards = response.data.rewards })
        end
        Events.Broadcast(Constants.EventNames.OnMonthCardUpdate)
    end)
end

function StoreItemCard:DrawClick()
    local isDraw = StoreUtils.GetStoreComp():IsMonthCardDrawRewards(self.monthCardId)
    local info = StoreUtils.GetStoreComp():GetMonthCardInfo(self.monthCardId)
    if not isDraw then
         GameUtils.Toast(localize("奖励已领取"))
        return
    end
    GameUtils.Request(Interfaces.StoreMonthCardDrawRewards ,  {cardId = info.monthCardId}, function(request, response)
        local rewardData = response.data.rewards
        GoodsUtils.DrawRewards(rewardData)
        info:SetDrawRewards(1)


        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewardData ,cb = function()
            self:AfterDraws()
        end} })
    end)
end

function StoreItemCard:AfterDraws()
    local info = StoreUtils.GetStoreComp():GetMonthCardInfo(self.monthCardId)
    ---@type MonthCardVo
    local vo =  CfUtils.GetCfVo(AutoIds.IdSetting602, "MonthCardVo" , self.monthCardId)
    if vo.type == MONTH_CARD_TYPE.COMMON then
        info.leftDrawnNum = info.leftDrawnNum -1
        if info.leftDrawnNum <= 0  then
            local monthCard = StoreUtils.GetStoreComp():GetMonthCardInfo(self.monthCardId)
            if table.count(monthCard.prices) > 0 then
                local goodsId = checkNumber(table.takeFirst(table.keys(monthCard.prices)))
                local dojo = monthCard.prices[tostring(goodsId)]
                local price = checkNumber(dojo.current)
                ServerDifferenceMgr:WrapPrimaryCurrencyBuy({
                    currency = goodsId,
                    current = price,
                },Bind(self,self.RequestBuyUseCurrency))
            else 
                GameUtils.SecondConfirm(localize('月卡到期，是否立即续费'), function()
                    SDKService:GetInstance():PayMoney({
                        productId = info.productId,
                        channelProductId = info.channelProductId,
                        productDesc = localize("购买月卡"),
                        payAmount = info.price,
                        data = info
                    })
                end)
            end 
        end
        self:RefreshCommonMonthCard(vo)
    end
    StoreUtils.GetStoreComp():CheckMonthCardRed()
    self:RefreshUI(vo)
end

function StoreItemCard:RefreshCard(monthCardId)
    self.monthCardId = monthCardId
    ---@type MonthCardVo
    local vo =  CfUtils.GetCfVo(AutoIds.IdSetting602, "MonthCardVo" , monthCardId)
    self.type = checkInt(vo.type)
    self:RefreshUI(vo)
    if self.type == MONTH_CARD_TYPE.COMMON then
        self:RefreshCommonMonthCard(vo)
    end
end

--- 刷新常规月卡
---@param vo MonthCardVo
function StoreItemCard:RefreshCommonMonthCard(vo)
    local monthCardInfo = StoreUtils.GetStoreComp():GetMonthCardInfo(self.monthCardId)
    local leftSeconds = monthCardInfo.leftSeconds
    local t = CfUtils.GetTimeData(leftSeconds)
    CfUtils.FillText(self.TxtInEffect ,localize("生效中")  )--localize("剩余:_num_次",{_num_ = monthCardInfo.leftDrawnNum } ))
    local isCardActive = StoreUtils.GetStoreComp():IsMonthCardActive(self.monthCardId)
    if isCardActive then
        CfUtils.FillText(self.TxtDay, monthCardInfo.leftDrawnNum)
        CfUtils.SetUISwitchText(self.TxtDay,monthCardInfo.leftDrawnNum > 3 and 1 or 2)
        if checkNumber(monthCardInfo.leftDrawnNum) <= 0 then
            CfUtils.SetActive(self.RemainDayGroup.gameObject,false)
        end
    end
end

--- 刷新常规月卡
---@param vo MonthCardVo
function StoreItemCard:RefreshUI(vo)
    local isCardActive = StoreUtils.GetStoreComp():IsMonthCardActive(self.monthCardId)
    local info = StoreUtils.GetStoreComp():GetMonthCardInfo(self.monthCardId)
    if vo.type == MONTH_CARD_TYPE.LIFELONG then
        KTool.SetActive(self.CanPay, not isCardActive)
        KTool.SetActive(self.HasPay, isCardActive)
    else
        KTool.SetActive(self.RemainDayGroup.gameObject, isCardActive)
        if isCardActive then
            KTool.SetActive(self.HasPay , info.isRenew ~= 1)
        else
            KTool.SetActive(self.HasPay , false)
        end
    end
    KTool.SetActive(self.NoActive.gameObject,not isCardActive)

    if not isCardActive then
        KTool.SetActive(self.NotDrawRewards,false)
        KTool.SetActive(self.DrawRewards,false)
    else
        local isDraw = StoreUtils.GetStoreComp():IsMonthCardDrawRewards(self.monthCardId)
        KTool.SetActive(self.NotDrawRewards,isDraw)
        KTool.SetActive(self.DrawRewards,not isDraw )
    end
    ---@type CommonGoodsList
    local rewardEnv = CfUtils.GetLuaScr(self.CommonGoodsList,"Game.Behaviours.CommonGoodsListLight")
    -- local rewardEnv = CfUtils.GetLuaScr(self.CommonGoodsList, "Game.Behaviours.CommonGoodsList")
    rewardEnv:FreshBaseUI(vo.rewards)

    local firstRewards = vo.firstRewards
    ---@type CommonGoodsList
    local firstRewardEnv = CfUtils.GetLuaScr(self.CommonGoodsListLight,"Game.Behaviours.CommonGoodsListLight")
    firstRewardEnv:FreshBaseUI(firstRewards)


    local TxtPrice =  self.CanPay.transform:Find("DiscountPrice/Price1/TxtPrice")
    local IconPrice = self.CanPay.transform:Find("DiscountPrice/Price1/ImgIcon")
    if vo.type == MONTH_CARD_TYPE.LIFELONG then
        TxtPrice =  self.CanPay.transform:Find("Price1/TxtPrice")
        IconPrice = self.CanPay.transform:Find("Price1/ImgIcon")
    end
    if table.count(info.prices) > 0 then
        CfUtils.SetActive(IconPrice,true)
        local goodsId = checkNumber(table.takeFirst(table.keys(info.prices)))
        local currencyVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        local dojo = info.prices[tostring(goodsId)]
        local price = checkNumber(dojo.current)
        CfUtils.FillImage(IconPrice , currencyVo.photoPath)
        CfUtils.FillText(TxtPrice,price)

        if vo.type == MONTH_CARD_TYPE.COMMON then
            ---价格一样  说明是原价
            local originalPriceDojo = info.initPrices[tostring(goodsId)]
            local originalPrice = checkNumber(originalPriceDojo.current)
            local Price2 = self.CanPay.transform:Find("DiscountPrice/Price2")
            local LimitTime = self.CanPay.transform:Find("LimitTime")
            CfUtils.SetActive(Price2,originalPrice ~= price)
            CfUtils.SetActive(LimitTime.gameObject,originalPrice ~= price)
            if originalPrice ~= price and checkNumber(info.renewLeftSeconds) > 0 then
                local icon = Price2.transform:Find("ImgIcon")
                local txt =  Price2.transform:Find("TextOriginal")
                CfUtils.SetActive(icon.gameObject, true)
                CfUtils.FillImage(icon , currencyVo.photoPath)
                CfUtils.FillText(txt,originalPrice)

                local txtTime = LimitTime.transform:Find("TxtTime")
                if checkNumber(info.renewLeftSeconds) > 0 then
                    CfUtils.FillText(txtTime,CfUtils.GetTimeHMS4(info.renewLeftSeconds))
                else
                    CfUtils.FillText(txtTime,CfUtils.GetTimeHMS4(0))
                end
            end
        end
    else
        local windowsPriceId = CfUtils.GetWindowsPriceId(info)
        CfUtils.FillText(TxtPrice,CfUtils.GetCustomDisplayPrice(windowsPriceId,info.channelProductId,30))
        CfUtils.SetActive(IconPrice,false)

        if vo.type == MONTH_CARD_TYPE.COMMON then
            ---价格一样  说明是原价
            local Price2 = self.CanPay.transform:Find("DiscountPrice/Price2")
            local LimitTime = self.CanPay.transform:Find("LimitTime")
            CfUtils.SetActive(Price2,info.price ~= info.initPrice)
            CfUtils.SetActive(LimitTime.gameObject,info.price ~= info.initPrice)
            if info.price ~= info.initPrice then
                local icon = Price2.transform:Find("ImgIcon")
                local txt =  Price2.transform:Find("TextOriginal")
                CfUtils.SetActive(icon.gameObject,false)
                CfUtils.FillText(txt,CfUtils.GetCustomDisplayPrice(info.initPrice,nil,30))

                local txtTime = LimitTime.transform:Find("TxtTime")
                if checkNumber(info.renewLeftSeconds) > 0 then
                    CfUtils.FillText(txtTime,CfUtils.GetTimeHMS4(info.renewLeftSeconds))
                else
                    CfUtils.FillText(txtTime,CfUtils.GetTimeHMS4(0))
                end
            end
        end
    end
    
end

function StoreItemCard:GetGoodsDes()
    local des = ""
    ---@type MonthCardVo
    local vo =  CfUtils.GetCfVo(AutoIds.IdSetting602, "MonthCardVo" , self.monthCardId)
    if not isNull(vo) then
        local rewards = vo.firstRewards
        for i, v in pairs(rewards) do
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(v.goodsId)
            if not isNull(goodsVo) then
                des = des..string.format("<color=#e71f55>%s</color>",v.goodsNum)..goodsVo.name
            end
            if i ~= #rewards then
                des = des.."+"
            end
        end
    end
    return des
end

function StoreItemCard:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return StoreItemCard